#!/usr/bin/env python3
"""Generate the small, dependency-free Xcode project deterministically."""
from pathlib import Path
import hashlib
root = Path(__file__).resolve().parent.parent

def ident(value): return hashlib.sha1(value.encode()).hexdigest()[:24].upper()
def obj(name, text): return f'{ident(name)} = {{ {text} }};'
files = sorted((root/'WoolooMobile').glob('*.swift'))
objects=[]
for file in files:
    objects += [obj(str(file.name),f'isa = PBXFileReference; lastKnownFileType = sourcecode.swift; path = "{file.name}"; sourceTree = "<group>";'),obj('build'+file.name,f'isa = PBXBuildFile; fileRef = {ident(file.name)};')]
objects += [obj('notices','isa = PBXFileReference; lastKnownFileType = text; path = ThirdPartyNotices.txt; sourceTree = \"<group>\";'),obj('buildnotices',f'isa = PBXBuildFile; fileRef = {ident("notices")};')]
objects += [obj('assets','isa = PBXFileReference; lastKnownFileType = folder.assetcatalog; path = Assets.xcassets; sourceTree = "<group>";'),obj('buildassets',f'isa = PBXBuildFile; fileRef = {ident("assets")};'),obj('privacy','isa = PBXFileReference; lastKnownFileType = text.xml; path = PrivacyInfo.xcprivacy; sourceTree = "<group>";'),obj('buildprivacy',f'isa = PBXBuildFile; fileRef = {ident("privacy")};'),obj('product','isa = PBXFileReference; explicitFileType = wrapper.application; path = "Wooloo Mobile.app"; sourceTree = BUILT_PRODUCTS_DIR;')]
objects += [obj('rootgroup',f'isa = PBXGroup; children = ({ident("appgroup")}, {ident("products")}); sourceTree = "<group>";'),obj('appgroup',f'isa = PBXGroup; path = WoolooMobile; sourceTree = "<group>"; children = ({", ".join(ident(f.name) for f in files)}, {ident("assets")}, {ident("privacy")}, {ident("notices")});'),obj('products',f'isa = PBXGroup; name = Products; children = ({ident("product")}); sourceTree = "<group>";')]
objects += [obj('sources',f'isa = PBXSourcesBuildPhase; buildActionMask = 2147483647; files = ({", ".join(ident("build"+f.name) for f in files)}); runOnlyForDeploymentPostprocessing = 0;'),obj('resources',f'isa = PBXResourcesBuildPhase; buildActionMask = 2147483647; files = ({ident("buildassets")}, {ident("buildprivacy")}, {ident("buildnotices")}); runOnlyForDeploymentPostprocessing = 0;'),obj('frameworks',f'isa = PBXFrameworksBuildPhase; buildActionMask = 2147483647; files = ({ident("buildcore")}); runOnlyForDeploymentPostprocessing = 0;'),obj('buildcore',f'isa = PBXBuildFile; productRef = {ident("core")};'),obj('core',f'isa = XCSwiftPackageProductDependency; productName = WoolooCore;'),obj('localpackage','isa = XCLocalSwiftPackageReference; relativePath = .;')]
for name in ['Debug','Release']:
    objects += [obj('proj'+name,f'isa = XCBuildConfiguration; name = {name}; buildSettings = {{ CLANG_ENABLE_MODULES = YES; SDKROOT = iphoneos; IPHONEOS_DEPLOYMENT_TARGET = 17.0; SWIFT_VERSION = 5.0; }};')]
    settings='ASSETCATALOG_COMPILER_APPICON_NAME = AppIcon; CODE_SIGN_STYLE = Automatic; CURRENT_PROJECT_VERSION = 1; GENERATE_INFOPLIST_FILE = NO; INFOPLIST_FILE = WoolooMobile/Info.plist; MARKETING_VERSION = 0.1.0; PRODUCT_BUNDLE_IDENTIFIER = dev.wooloo.mobile.ios; PRODUCT_NAME = "Wooloo Mobile"; SUPPORTED_PLATFORMS = "iphoneos iphonesimulator"; TARGETED_DEVICE_FAMILY = "1,2"; SWIFT_EMIT_LOC_STRINGS = YES; SWIFT_VERSION = 5.0; IPHONEOS_DEPLOYMENT_TARGET = 17.0;'
    settings += ' SWIFT_OPTIMIZATION_LEVEL = "-Onone"; DEBUG_INFORMATION_FORMAT = dwarf;' if name=='Debug' else ' SWIFT_OPTIMIZATION_LEVEL = "-O"; DEBUG_INFORMATION_FORMAT = "dwarf-with-dsym";'
    objects += [obj('app'+name,f'isa = XCBuildConfiguration; name = {name}; buildSettings = {{ {settings} }};')]
for prefix in ['proj','app']:
    objects += [obj(prefix+'configs',f'isa = XCConfigurationList; buildConfigurations = ({ident(prefix+"Debug")}, {ident(prefix+"Release")}); defaultConfigurationIsVisible = 0; defaultConfigurationName = Release;')]
objects += [obj('target',f'isa = PBXNativeTarget; buildConfigurationList = {ident("appconfigs")}; buildPhases = ({ident("sources")}, {ident("frameworks")}, {ident("resources")}); buildRules = (); dependencies = (); name = WoolooMobile; packageProductDependencies = ({ident("core")}); productName = WoolooMobile; productReference = {ident("product")}; productType = "com.apple.product-type.application";'),obj('project',f'isa = PBXProject; attributes = {{ LastUpgradeCheck = 2660; }}; buildConfigurationList = {ident("projconfigs")}; compatibilityVersion = "Xcode 14.0"; developmentRegion = en; hasScannedForEncodings = 0; knownRegions = (en, Base); mainGroup = {ident("rootgroup")}; packageReferences = ({ident("localpackage")}); productRefGroup = {ident("products")}; projectDirPath = ""; projectRoot = ""; targets = ({ident("target")});')]
p=root/'WoolooMobile.xcodeproj'
p.mkdir(exist_ok=True)
(p/'project.pbxproj').write_text('// !$*UTF8*$!\n{ archiveVersion = 1; classes = {}; objectVersion = 56; objects = {\n'+'\n'.join(objects)+'\n}; rootObject = '+ident('project')+'; }\n')
(p/'xcshareddata/xcschemes').mkdir(parents=True,exist_ok=True)
(p/'xcshareddata/xcschemes/WoolooMobile.xcscheme').write_text(f'''<?xml version="1.0" encoding="UTF-8"?>
<Scheme LastUpgradeVersion="2660" version="1.3"><BuildAction parallelizeBuildables="YES" buildImplicitDependencies="YES"><BuildActionEntries><BuildActionEntry buildForTesting="YES" buildForRunning="YES" buildForProfiling="YES" buildForArchiving="YES" buildForAnalyzing="YES"><BuildableReference BuildableIdentifier="primary" BlueprintIdentifier="{ident('target')}" BuildableName="Wooloo Mobile.app" BlueprintName="WoolooMobile" ReferencedContainer="container:WoolooMobile.xcodeproj"/></BuildActionEntry></BuildActionEntries></BuildAction><LaunchAction buildConfiguration="Debug" selectedDebuggerIdentifier="Xcode.DebuggerFoundation.Debugger.LLDB" selectedLauncherIdentifier="Xcode.IDEFoundation.Launcher.LLDB" launchStyle="0" useCustomWorkingDirectory="NO" ignoresPersistentStateOnLaunch="NO" debugDocumentVersioning="YES" debugServiceExtension="internal" allowLocationSimulation="YES"><BuildableProductRunnable runnableDebuggingMode="0"><BuildableReference BuildableIdentifier="primary" BlueprintIdentifier="{ident('target')}" BuildableName="Wooloo Mobile.app" BlueprintName="WoolooMobile" ReferencedContainer="container:WoolooMobile.xcodeproj"/></BuildableProductRunnable></LaunchAction><ProfileAction buildConfiguration="Release" shouldUseLaunchSchemeArgsEnv="YES" savedToolIdentifier="" useCustomWorkingDirectory="NO" debugDocumentVersioning="YES"/><AnalyzeAction buildConfiguration="Debug"/><ArchiveAction buildConfiguration="Release" revealArchiveInOrganizer="YES"/></Scheme>''')
